import{_ as a,a as r,c as i,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"琅琊榜","description":"江左盟宗主梅长苏以病弱谋士的身份进入京城，卷入皇子争位与旧案纠葛。他必须在有限的时间和身体条件下安排行动，同时处理与旧友、亲人之间无法公开说明的关系。","frontmatter":{"title":"琅琊榜","description":"江左盟宗主梅长苏以病弱谋士的身份进入京城，卷入皇子争位与旧案纠葛。他必须在有限的时间和身体条件下安排行动，同时处理与旧友、亲人之间无法公开说明的关系。","media":{"category":"series","year":2015,"doubanRating":9.4,"ratingCheckedAt":"2026-10-31","ratingSource":"https://www.douban.com/doulist/134440083/","ratingSourceType":"豆瓣公开片单"},"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"影视导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"影视 · 电视剧","summary":"江左盟宗主梅长苏以病弱谋士的身份进入京城，卷入皇子争位与旧案纠葛。他必须在有限的时间和身体条件下安排行动，同时处理与旧友、亲人之间无法公开说明的关系。","status":"active","related":[{"title":"大明王朝1566","link":"/life/personal/media/series/ming-dynasty-1566","kind":"影视导读","scope":"general","audience":"general"},{"title":"是，大臣 第一季","link":"/life/personal/media/series/yes-minister-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"红楼梦（1987）","link":"/life/personal/media/series/dream-of-the-red-chamber-1987","kind":"影视导读","scope":"general","audience":"general"},{"title":"西游记（1986）","link":"/life/personal/media/series/journey-to-the-west-1986","kind":"影视导读","scope":"general","audience":"general"},{"title":"老友记 第一季","link":"/life/personal/media/series/friends-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"请回答1988","link":"/life/personal/media/series/reply-1988","kind":"影视导读","scope":"general","audience":"general"},{"title":"白色巨塔（2003）","link":"/life/personal/media/series/the-white-tower-2003","kind":"影视导读","scope":"general","audience":"general"},{"title":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale","kind":"影视导读","scope":"general","audience":"general"},{"title":"武林外传","link":"/life/personal/media/series/my-own-swordsman","kind":"影视导读","scope":"general","audience":"general"},{"title":"我的团长我的团","link":"/life/personal/media/series/my-chief-and-my-regiment","kind":"影视导读","scope":"general","audience":"general"},{"title":"非自然死亡","link":"/life/personal/media/series/unnatural","kind":"影视导读","scope":"general","audience":"general"},{"title":"机智医生生活 第一季","link":"/life/personal/media/series/hospital-playlist-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"亮剑","link":"/life/personal/media/series/bright-sword","kind":"影视导读","scope":"general","audience":"general"},{"title":"后宫·甄嬛传","link":"/life/personal/media/series/empresses-in-the-palace","kind":"影视导读","scope":"general","audience":"general"},{"title":"漫长的季节","link":"/life/personal/media/series/the-long-season","kind":"影视导读","scope":"general","audience":"general"},{"title":"我们与恶的距离","link":"/life/personal/media/series/the-world-between-us","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"亮剑","link":"/life/personal/media/series/bright-sword"},"next":{"text":"后宫·甄嬛传","link":"/life/personal/media/series/empresses-in-the-palace"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"亮剑","link":"/life/personal/media/series/bright-sword"},"next":{"text":"后宫·甄嬛传","link":"/life/personal/media/series/empresses-in-the-palace"}},"headers":[],"relativePath":"life/personal/media/series/nirvana-in-fire.md","filePath":"life/personal/media/series/nirvana-in-fire.md"}'),n={name:"life/personal/media/series/nirvana-in-fire.md"};function l(s,e,d,o,p,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="琅琊榜" tabindex="-1">琅琊榜 <a class="header-anchor" href="#琅琊榜" aria-label="Permalink to &quot;琅琊榜&quot;">​</a></h1><p><a href="./../overview">影视总览</a> · <a href="./overview">电视剧片单</a></p><h2 id="基本资料" tabindex="-1">基本资料 <a class="header-anchor" href="#基本资料" aria-label="Permalink to &quot;基本资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td>原名 / 别名</td><td>Nirvana in Fire</td></tr><tr><td>年份 / 地区</td><td>2015 / 中国大陆</td></tr><tr><td>类型</td><td>剧情 / 古装 / 权谋</td></tr><tr><td>导演 / 主创</td><td>孔笙、李雪；编剧海宴</td></tr><tr><td>主要演员 / 配音</td><td>胡歌、刘涛、王凯、黄维德</td></tr><tr><td>篇幅 / 版本</td><td>54 集，单集约 45 分钟</td></tr><tr><td>豆瓣参考评分</td><td><strong>9.4 / 10</strong></td></tr><tr><td>评分依据</td><td><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>（豆瓣公开片单）</td></tr><tr><td>查询日期</td><td>2026-10-31</td></tr></tbody></table><p>评分为本次查询可读取的豆瓣页面值，网页缓存可能滞后，不能保证与此刻实时值一致。 篇幅按常见版本作近似说明，片头、花絮及剪辑差异可能影响播放时长。</p><h2 id="创作背景与资料" tabindex="-1">创作背景与资料 <a class="header-anchor" href="#创作背景与资料" aria-label="Permalink to &quot;创作背景与资料&quot;">​</a></h2><p>作品改编自海宴同名小说，海宴也参与剧本把关。播出前的采访资料说明，改编保留了主要人物框架与故事方向，同时对细节进行调整；这里的架空世界应与真实朝代历史分开。<a href="https://www.chinawriter.com.cn/news/2015/2015-09-18/253694.html" target="_blank" rel="noopener noreferrer">原作者谈改编</a></p><p>梅长苏既是谋士，也是被过去牵动的人。理解这两种身份如何互相支持又互相伤害，比把剧情只当成聪明人连续取胜更接近作品的情感重心。</p><h2 id="剧情介绍" tabindex="-1">剧情介绍 <a class="header-anchor" href="#剧情介绍" aria-label="Permalink to &quot;剧情介绍&quot;">​</a></h2><p>江左盟宗主梅长苏以病弱谋士的身份进入京城，卷入皇子争位与旧案纠葛。他必须在有限的时间和身体条件下安排行动，同时处理与旧友、亲人之间无法公开说明的关系。</p><p>权谋提供故事的外部结构，身份、信任与旧日创伤则推动情感线。人物所争取的不只是一次胜负，也包括被权力改变的事实能否重新得到承认。</p><h2 id="特色与看点" tabindex="-1">特色与看点 <a class="header-anchor" href="#特色与看点" aria-label="Permalink to &quot;特色与看点&quot;">​</a></h2><h3 id="_1-叙事与人物" tabindex="-1">1. 叙事与人物 <a class="header-anchor" href="#_1-叙事与人物" aria-label="Permalink to &quot;1. 叙事与人物&quot;">​</a></h3><p>梅长苏经常掌握比周围人更多的信息，悬念来自他如何安排步骤以及是否愿意付出代价。靖王等人的反应，则让谋略与原则之间保持张力。</p><h3 id="_2-主题与表达" tabindex="-1">2. 主题与表达 <a class="header-anchor" href="#_2-主题与表达" aria-label="Permalink to &quot;2. 主题与表达&quot;">​</a></h3><p>画面中的庭院、雪、炉火与服饰形成克制的美术风格，与主人公的身体状态和隐忍情绪呼应。动作之外的沉默与称呼变化，也在推进关系。</p><h2 id="主要阵营怎样逐渐清晰" tabindex="-1">主要阵营怎样逐渐清晰 <a class="header-anchor" href="#主要阵营怎样逐渐清晰" aria-label="Permalink to &quot;主要阵营怎样逐渐清晰&quot;">​</a></h2><p>梅长苏进入京城后，被太子、誉王等势力看作可以争取的资源，他却有自己的行动路线。靖王的原则、霓凰对旧人的记忆、蒙挚的支持与蔺晨的关照，分别从政治、情感和身体条件约束他的计划。</p><p>反派阵营也不只负责设障，皇帝的猜疑、掌权者对安全的解释，说明旧案为何难以通过一份证据直接纠正。权力不仅决定事实能否被说出，也决定谁有资格说。</p><h2 id="三阶段观看路线" tabindex="-1">三阶段观看路线 <a class="header-anchor" href="#三阶段观看路线" aria-label="Permalink to &quot;三阶段观看路线&quot;">​</a></h2><p>进入京城与建立信任，是让棋局具备行动条件；一系列案件与阵营冲突，逐步改变可公开讨论的问题；后段则让旧案与人物身份的压力集中出现。初看不要急着记住全部职位，可先抓住梅长苏为何选择帮助某个人。</p><p>计划经常依赖他人配合，但配合者未必知道全部真相。这里存在一个持续问题：为了实现被认为正当的目标，能否替朋友决定他应承担的风险？</p><h2 id="场景、称呼与身体细节" tabindex="-1">场景、称呼与身体细节 <a class="header-anchor" href="#场景、称呼与身体细节" aria-label="Permalink to &quot;场景、称呼与身体细节&quot;">​</a></h2><p>炉火、药、披风与等待反复提醒观众，主角不是拥有无限时间的全能指挥者。与此相对，庭院和礼仪保持克制，使情绪常在一瞬间的称呼变化里显露。</p><p>靖王面对梅长苏时的判断，也值得与观众知道的信息分开。观众能够同情隐瞒，不代表被隐瞒的人就应天然理解。看见这种认知差，人物冲突才不会只剩谁更聪明。</p><h2 id="评价与重看方法" tabindex="-1">评价与重看方法 <a class="header-anchor" href="#评价与重看方法" aria-label="Permalink to &quot;评价与重看方法&quot;">​</a></h2><p>作品的优势是长线情感回收、表演默契与整齐的美术气质；局限是主角掌握的信息优势较大，部分行动显得过于精确，普通人的经验仍主要服务于政治与旧案主线。</p><p>重看可选一个案件，列出每方知道的事实和以为知道的事实，检查计划如何利用差距。再回到私人关系，观察成功并未消除哪些损失：这样能同时看见谋略的组织力和它无法替代的人生。</p><h2 id="适合谁看与观看建议" tabindex="-1">适合谁看与观看建议 <a class="header-anchor" href="#适合谁看与观看建议" aria-label="Permalink to &quot;适合谁看与观看建议&quot;">​</a></h2><p>适合喜欢长线伏笔、古装群像和情感回收的人。前几集人物较多，可简单记录阵营；故事是架空创作，建议按顺序看，避免提前查身份与旧案结局。</p><h2 id="看后思考" tabindex="-1">看后思考 <a class="header-anchor" href="#看后思考" aria-label="Permalink to &quot;看后思考&quot;">​</a></h2><p>为了恢复正义，使用复杂谋略会带来怎样的道德压力？旧身份与新角色之间，人物如何保留自我？</p><p>创作事实见段落所附来源；人物、场景与评价部分为本站观影分析，不代表主创唯一解释。正文保留主要故事体验，不展开关键结局。评分用于辅助选片，不代表每位观众的感受。</p><h2 id="资料与复核入口" tabindex="-1">资料与复核入口 <a class="header-anchor" href="#资料与复核入口" aria-label="Permalink to &quot;资料与复核入口&quot;">​</a></h2><ul><li><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>：本页评分依据；查询于 2026-10-31。</li><li><a href="https://movie.douban.com/subject/25754848/" target="_blank" rel="noopener noreferrer">《琅琊榜》豆瓣条目</a>：版本与后续评分复核入口；部分条目可能要求验证。</li></ul><p><a href="./overview">返回电视剧片单</a> · <a href="./../overview">返回影视总览</a></p>',36)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
